//! Render every PDF model for every example input
//! (`eks::models::examples()`) and compare the output against the models
//! as they are on `origin/main`.
//!
//! The models are Rust code compiled into the `eks` crate, so the `main`
//! versions cannot be rendered from this checkout directly. When the baseline
//! (`tmp/main-pdfs/`) is missing, it is generated by checking `origin/main`
//! out into a temporary git worktree and running that checkout's own
//! `pdf_diff --save-baseline`; an existing baseline is reused, delete
//! `tmp/main-pdfs/` to regenerate it.
//!
//! The current models are rendered into `tmp/current-pdfs/`; visual diffs of
//! changed PDFs go to `tmp/diffs/` and a summary to `tmp/results.md`.
//!
//! Requires `diff-pdf` (`apt-get install diff-pdf-wx` / `brew install diff-pdf`).
//!
//! Run with `cargo run -p eks-development --bin pdf_diff`

use std::{
    collections::BTreeSet,
    env,
    fmt::Write as _,
    fs,
    path::{Path, PathBuf},
    process::Command,
};

use anyhow::{Context, Result};
use tracing::info;
use tracing_subscriber::{Layer, layer::SubscriberExt, util::SubscriberInitExt};

const DIFF_PDF_BINARY: &str = "diff-pdf";
const TMP_DIR_NAME: &str = "tmp";
const CURRENT_PDFS_DIR_NAME: &str = "current-pdfs";
const MAIN_PDFS_DIR_NAME: &str = "main-pdfs";
const MAIN_WORKTREE_DIR_NAME: &str = "main-worktree";
const DIFFS_DIR_NAME: &str = "diffs";
const RESULTS_FILE_NAME: &str = "results.md";
const GIT_MAIN_REF: &str = "origin/main";

type DiffSummaryRow = (String, String, &'static str);

/// Return whether a binary name resolves to an executable file somewhere on `PATH`.
fn binary_in_path(name: &str) -> bool {
    if let Ok(paths) = env::var("PATH") {
        for dir in env::split_paths(&paths) {
            if dir.join(name).is_file() {
                return true;
            }
        }
    }
    false
}

/// Ensure the `diff-pdf` executable is available before starting any work.
fn ensure_diff_pdf_is_installed() -> Result<()> {
    if !binary_in_path(DIFF_PDF_BINARY) {
        // `sudo apt-get install -y diff-pdf-wx` or `brew install diff-pdf`
        anyhow::bail!(
            "`diff-pdf` is not installed or not found in PATH. Please install it to use this tool."
        );
    }
    Ok(())
}

/// Render every example input into `output_root` and return the written PDF
/// file names.
fn render_all(output_root: &Path) -> Result<Vec<String>> {
    fs::create_dir_all(output_root)
        .with_context(|| format!("Failed to create {}", output_root.display()))?;

    let mut rendered = Vec::new();
    for example in eks::models::examples() {
        let name = example.name;
        let pdf_name = format!("{name}.pdf");
        let bytes = example
            .render()
            .map_err(|err| anyhow::anyhow!("{err}"))
            .with_context(|| format!("Failed to render {name}"))?;

        let output = output_root.join(&pdf_name);
        fs::write(&output, &bytes)
            .with_context(|| format!("Failed to write {}", output.display()))?;
        info!(
            name,
            output = %output.display(),
            pdf_size_bytes = bytes.len(),
            "Rendered PDF"
        );
        rendered.push(pdf_name);
    }
    Ok(rendered)
}

/// Run `diff-pdf` for two rendered PDFs and report whether their contents differ.
fn diff_pdfs(current_pdf: &Path, main_pdf: &Path, diff_pdf: &Path) -> Result<bool> {
    let status = Command::new(DIFF_PDF_BINARY)
        .arg(format!("--output-diff={}", diff_pdf.display()))
        .arg("--skip-identical")
        .arg(main_pdf)
        .arg(current_pdf)
        .status()
        .context("Failed to run diff-pdf")?;

    match status.code() {
        Some(0) => Ok(false),
        Some(1) => Ok(true),
        Some(code) => anyhow::bail!("diff-pdf failed with exit code {code}"),
        None => anyhow::bail!("diff-pdf terminated by signal"),
    }
}

fn status_indicator(status: &str) -> &'static str {
    match status {
        "added" => "🟢",
        "deleted" => "🔴",
        "changed" => "🟠",
        "identical" => "🔵",
        _ => "⚪",
    }
}

/// Build the Markdown summary table written to `tmp/results.md`.
fn build_report(results: &[DiffSummaryRow]) -> Result<String> {
    let mut report = String::new();
    writeln!(report, "| Template | Input | Status |")?;
    writeln!(report, "| --- | --- | --- |")?;
    for (template, input_name, status) in results {
        writeln!(
            report,
            "| {template} | {input_name} | {} {status} |",
            status_indicator(status),
        )?;
    }
    Ok(report)
}

/// Compare the rendered PDFs against the baseline and summarize per input.
fn compare(project_dir: &Path, rendered: Vec<String>) -> Result<Vec<DiffSummaryRow>> {
    let tmp_dir = project_dir.join(TMP_DIR_NAME);
    let current_root = tmp_dir.join(CURRENT_PDFS_DIR_NAME);
    let main_root = tmp_dir.join(MAIN_PDFS_DIR_NAME);
    let diffs_root = tmp_dir.join(DIFFS_DIR_NAME);
    fs::create_dir_all(&diffs_root).context("Failed to create tmp/diffs")?;

    let baseline: BTreeSet<String> = fs::read_dir(&main_root)?
        .filter_map(Result::ok)
        .filter_map(|entry| entry.file_name().into_string().ok())
        .filter(|name| name.ends_with(".pdf"))
        .collect();

    let mut results = Vec::new();
    for pdf_name in &rendered {
        let template = pdf_name.split("-example-").next().unwrap_or(pdf_name);
        let row = if baseline.contains(pdf_name) {
            let diff_pdf = diffs_root.join(pdf_name);
            let changed = diff_pdfs(
                &current_root.join(pdf_name),
                &main_root.join(pdf_name),
                &diff_pdf,
            )?;
            if !changed {
                let _ = fs::remove_file(&diff_pdf);
            }
            if changed { "changed" } else { "identical" }
        } else {
            "added"
        };
        results.push((template.to_string(), pdf_name.clone(), row));
    }
    for pdf_name in baseline {
        if !rendered.contains(&pdf_name) {
            let template = pdf_name
                .split("-example-")
                .next()
                .unwrap_or(&pdf_name)
                .to_string();
            results.push((template, pdf_name, "deleted"));
        }
    }
    results.sort_unstable();
    Ok(results)
}

/// Run a command in `cwd`, inheriting stdout/stderr, and fail on a non-zero
/// exit.
fn run_in(cwd: &Path, program: &str, args: &[&str]) -> Result<()> {
    let status = Command::new(program)
        .args(args)
        .current_dir(cwd)
        .status()
        .with_context(|| format!("Failed to run `{program}`"))?;
    if !status.success() {
        anyhow::bail!("`{program} {}` failed with {status}", args.join(" "));
    }
    Ok(())
}

/// Remove the baseline worktree, ignoring failures (it may not exist).
fn remove_worktree(project_dir: &Path, worktree: &Path) {
    let _ = Command::new("git")
        .args(["worktree", "remove", "--force"])
        .arg(worktree)
        .current_dir(project_dir)
        .output();
}

/// Render the models as they are on `origin/main` into `tmp/main-pdfs/`:
/// check that ref out into a temporary git worktree and run its own
/// `pdf_diff -- --save-baseline` there, then copy the PDFs over.
fn generate_baseline(project_dir: &Path) -> Result<()> {
    info!(
        "No baseline in tmp/{MAIN_PDFS_DIR_NAME}; rendering the {GIT_MAIN_REF} models into it (this builds the main branch once)"
    );

    let worktree = project_dir.join(TMP_DIR_NAME).join(MAIN_WORKTREE_DIR_NAME);
    remove_worktree(project_dir, &worktree); // from an aborted earlier run
    run_in(
        project_dir,
        "git",
        &[
            "worktree",
            "add",
            "--force",
            &worktree.to_string_lossy(),
            GIT_MAIN_REF,
        ],
    )?;

    let result = (|| {
        // Share the target directory so the worktree build reuses this
        // checkout's compiled dependencies (unless the caller already directs
        // builds elsewhere).
        let target_dir = env::var("CARGO_TARGET_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|_| project_dir.join("target"));
        let status = Command::new("cargo")
            .args([
                "run",
                "--locked",
                "--release",
                "-p",
                "eks-development",
                "--bin",
                "pdf_diff",
                "--",
                "--save-baseline",
            ])
            .env("CARGO_TARGET_DIR", &target_dir)
            .current_dir(&worktree)
            .status()
            .context("Failed to run cargo in the main worktree")?;
        if !status.success() {
            anyhow::bail!("rendering the {GIT_MAIN_REF} baseline failed with {status}");
        }

        let from = worktree.join(TMP_DIR_NAME).join(MAIN_PDFS_DIR_NAME);
        let to = project_dir.join(TMP_DIR_NAME).join(MAIN_PDFS_DIR_NAME);
        fs::create_dir_all(&to).with_context(|| format!("Failed to create {}", to.display()))?;
        let mut copied = 0;
        for entry in
            fs::read_dir(&from).with_context(|| format!("Failed to read {}", from.display()))?
        {
            let path = entry?.path();
            if path.extension().and_then(|ext| ext.to_str()) == Some("pdf") {
                fs::copy(&path, to.join(path.file_name().expect("file name")))
                    .with_context(|| format!("Failed to copy {}", path.display()))?;
                copied += 1;
            }
        }
        info!("Saved {copied} baseline PDFs to {}", to.display());
        Ok(())
    })();

    remove_worktree(project_dir, &worktree);
    result
}

/// Initialize tracing for this binary and limit output to this crate's logs.
fn init_tracing() {
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::fmt::layer().with_filter(tracing_subscriber::filter::filter_fn(
                |metadata| metadata.target().starts_with(env!("CARGO_CRATE_NAME")),
            )),
        )
        .init();
}

/// Render all PDF models into the baseline directory (`--save-baseline` mode).
fn save_baseline(tmp_dir: &Path) -> Result<()> {
    let main_root = tmp_dir.join(MAIN_PDFS_DIR_NAME);
    let rendered = render_all(&main_root)?;
    info!(
        "Saved {} baseline PDFs to {}",
        rendered.len(),
        main_root.display()
    );
    Ok(())
}

/// Render the current PDF models, diff them against the saved baseline
/// (generating it first if missing) and write the results report.
fn diff_against_baseline(project_dir: &Path, tmp_dir: &Path) -> Result<()> {
    ensure_diff_pdf_is_installed()?;

    if !tmp_dir.join(MAIN_PDFS_DIR_NAME).is_dir() {
        generate_baseline(project_dir)?;
    }

    let current_root = tmp_dir.join(CURRENT_PDFS_DIR_NAME);
    let rendered = render_all(&current_root)?;
    info!(
        "Rendered {} PDFs to {}",
        rendered.len(),
        current_root.display()
    );

    let results = compare(project_dir, rendered)?;
    for (_, input_name, status) in &results {
        info!("  {} {input_name}: {status}", status_indicator(status));
    }

    write_report(tmp_dir, &results)
}

/// Write the diff results report to the results file.
fn write_report(tmp_dir: &Path, results: &[DiffSummaryRow]) -> Result<()> {
    let report = build_report(results)?;
    let results_path = tmp_dir.join(RESULTS_FILE_NAME);
    fs::write(&results_path, &report)
        .with_context(|| format!("Failed to write {}", results_path.display()))?;
    info!("Wrote results to {}", results_path.display());

    Ok(())
}

fn run() -> Result<()> {
    let project_dir = env::current_dir().context("Failed to get current directory")?;
    let tmp_dir = project_dir.join(TMP_DIR_NAME);

    if env::args().any(|arg| arg == "--save-baseline") {
        save_baseline(&tmp_dir)
    } else {
        diff_against_baseline(&project_dir, &tmp_dir)
    }
}

/// Render the current PDF models for all example inputs and diff them against
/// the saved baseline.
fn main() -> Result<()> {
    init_tracing();
    run()
}
